import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as a}from"./chunks/remote_control.ss1psCxn.js";import{_ as i}from"./chunks/altitude_icon.CQEDErje.js";import{_ as r}from"./chunks/altitude_fw.DTK0l5oK.js";import{_ as o,o as d,c as l,al as n}from"./chunks/framework.7vp1BMOE.js";const R=JSON.parse('{"title":"Altitude Mode (Fixed-wing)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_modes_fw/altitude.md","filePath":"zh/flight_modes_fw/altitude.md"}'),s={name:"zh/flight_modes_fw/altitude.md"};function _(c,e,h,m,f,p){return d(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="altitude-mode-fixed-wing" tabindex="-1">Altitude Mode (Fixed-wing) <a class="header-anchor" href="#altitude-mode-fixed-wing" aria-label="Permalink to &quot;Altitude Mode (Fixed-wing)&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+a+'" title="Manual/Remote control required" width="30px"> <img src="'+i+'" title="Altitude required (e.g. Baro, Rangefinder)" width="30px"></p><p>The <em>Altitude</em> flight mode is the safest and easiest non-GPS manual mode. It makes it easier for pilots to control vehicle altitude, and in particular to reach and maintain a fixed altitude. The mode will not attempt to hold the vehicle course against wind. Airspeed is actively controlled if an airspeed sensor is installed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>Altitude mode</em> is similar to <a href="./../flight_modes_fw/cruise">Cruise mode</a> in that both modes level the vehicle and maintain altitude when sticks are released. The difference is that Cruise mode holds the actual flight path (course) steady against wind, while altitude just holds the heading.</p></div><p>The vehicle performs a <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated turn</a> if the roll sticks are non-zero, while the pitch stick controls the rate of ascent/descent. 滚动和俯仰是角度控制的（因此不可能实现飞机滚转或环绕）。</p><p>当所有遥控输入都居中时（无滚动、俯仰、偏航，油门约 50％），飞机将恢复直线水平飞行（受风影响）并保持其当前高度。 This makes it easy to recover from any problems when flying. Roll, pitch and yaw are all angle-controlled (so it is impossible to roll over or loop the vehicle).</p><p>The yaw stick can be used to increase/reduce the yaw rate of the vehicle in turns. If left at center the controller does the turn coordination by itself, meaning that it will apply the necessary yaw rate for the current roll angle to perform a smooth turn.</p><p>The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+r+'" alt="Altitude Control FW"></p><h2 id="技术总结" tabindex="-1">技术总结 <a class="header-anchor" href="#技术总结" aria-label="Permalink to &quot;技术总结&quot;">​</a></h2><p>Altitude mode like <a href="./../flight_modes_fw/stabilized">Stabilized mode</a> but with altitude stabilization. Airspeed is also stabilized if an airspeed sensor is present. 但是飞行过程并不稳定，可能被风吹飘离。</p><ul><li>回中的滚动/俯仰/偏航输入（在死区内）： <ul><li>Autopilot levels vehicle and maintains altitude and airspeed.</li></ul></li><li>外部中心： <ul><li>俯仰摇杆控制高度。</li><li>如果空速传感器已连接，油门杆控制飞机速度。 Without an airspeed sensor the vehicle will fly level at trim throttle (<a href="./../advanced_config/parameter_reference#FW_THR_TRIM">FW_THR_TRIM</a>), increasing or decreasing throttle as needed to climb or descend.</li><li>横滚摇杆控制横滚角度。 Autopilot will maintain <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated flight</a>.</li><li>偏航摇杆操纵会驱动方向舵（指令将被加到自动驾驶仪计算的指令中以维持 <a href="https://en.wikipedia.org/wiki/Coordinated_flight">协调飞行</a>）。 这和<a href="../flight_modes/stabilized_fw.md">稳定模式</a>一样。</li></ul></li><li>Manual control input is required (such as RC control, joystick).</li><li>An altitude measurement source is required (usually barometer or GPS)</li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>该模式受以下参数影响：</p><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="FW_AIRSPD_MIN"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a></td><td>最小空速/油门。 默认：10 m/s。</td></tr><tr><td><a id="FW_AIRSPD_MAX"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a></td><td>最大空速/油门。 默认：20 m/s。</td></tr><tr><td><a id="FW_AIRSPD_TRIM"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a></td><td>巡航速度。 默认：15 m/s。</td></tr><tr><td><a id="FW_MAN_P_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_P_MAX">FW_MAN_P_MAX</a></td><td>在高度稳定模式下手动控制的最大俯仰角。 Default: 45 degrees.</td></tr><tr><td><a id="FW_MAN_R_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_R_MAX">FW_MAN_R_MAX</a></td><td>在高度稳定模式下手动控制的最大滚转角。 Default: 45 degrees.</td></tr><tr><td><a id="FW_T_CLMB_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_CLMB_R_SP">FW_T_CLMB_R_SP</a></td><td>Max climb rate setpoint. 默认：3m/s。</td></tr><tr><td><a id="FW_T_SINK_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_SINK_R_SP">FW_T_SINK_R_SP</a></td><td>Max sink rate setpoint. Default: 2 m/s.</td></tr></tbody></table><h2 id="mavlink-commands" tabindex="-1">MAVLink Commands <a class="header-anchor" href="#mavlink-commands" aria-label="Permalink to &quot;MAVLink Commands&quot;">​</a></h2><p>The following commands are relevant to this mode:</p><ul><li><p><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a> — Sets the cruise airspeed for centred throttle stick.</p><p>This requires an airspeed sensor. Only the airspeed speed type is handled (<code>param1</code> must be <code>0</code>); other speed types are ignored. At centered throttle the vehicle holds the commanded airspeed (<code>param2</code>) if a positive value is set (non-positive values are ignored). The value is constrained between <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> and <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a>, and defaults to <a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a> if no airspeed has been commanded. Deflecting the throttle stick scales the airspeed toward <code>FW_AIRSPD_MIN</code> (back) or <code>FW_AIRSPD_MAX</code> (forward) around this value. The commanded airspeed resets to <code>FW_AIRSPD_TRIM</code> on every flight mode change.</p></li></ul><p>Note, other commands may be supported.</p>',22)])])}const w=o(s,[["render",_]]);export{R as __pageData,w as default};
